window.RP_SESSION={"id":"S-aae53f655bbf","messages":[{"id":"RP-III-0155056","time":"2026-08-21T01:26:00+09:00","room":"RP III","name":"인물 미확정 — 자연의 징조를 듣는 드루이드","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 바람이 속삭이면 자연의 벗은 듣는다. 그것이 드루이드의 일. 그리고 어떠한 이는 이따금, 자연에서 징조를 읽기도 한다.","characters":[]},{"id":"RP-III-0155057","time":"2026-08-21T01:26:00+09:00","room":"RP III","name":"인물 미확정 — 자연의 징조를 듣는 드루이드","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!예언","characters":[]},{"id":"RP-III-0155058","time":"2026-08-21T01:26:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...왕관의 주인이 나타날 것이다.","characters":[]},{"id":"RP-III-0155059","time":"2026-08-21T01:29:00+09:00","room":"RP III","name":"인물 미확정 — 자연의 징조를 듣는 드루이드","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그거 알아? 비어진 것이 있대. 그거 알아? 그것은 다시 제자리로 갈 것이래. 그것은 힘이래.\n 타고난 재능과 숙련을 통한 능력으로 정보가 범람한다.\n '알려줘서 고마워.'\n 그는 동물과 식물 친구들에게 감사인사를 했다. 사람의 말을 가지지 못하고 태어나 얻은 것이지만 굳게 믿을 것은 못 된다. 징조래봤자 거대한 옆으로 전달이고, 그러면서 의미가 퇴색된다.","characters":[]},{"id":"RP-III-0155060","time":"2026-08-21T01:30:00+09:00","room":"RP III","name":"인물 미확정 — 자연의 징조를 듣는 드루이드","profile":"올리브","identity":"reviewed","type":"dialogue","body":" ...뭐, 내 사랑만 무사하다면 되지 뭐. 일을 서둘러야지. 조만간 그 애 직장의 사람들을 불러볼까? 아냐, 사람을 만나는건 역시...","characters":[]},{"id":"RP-III-0155061","time":"2026-08-21T01:31:00+09:00","room":"RP III","name":"인물 미확정 — 자연의 징조를 듣는 드루이드","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 증오스러운 검은 것들이 자연의 것들을 앗아가지 않기를.","characters":[]},{"id":"RP-III-0155062","time":"2026-08-21T01:32:00+09:00","room":"RP III","name":"인물 미확정 — 자연의 징조를 듣는 드루이드","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0155063","time":"2026-08-21T01:32:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
